from h import *
add(6435021,"تازہ کالی پھلیوں کی سالسا",
"یہ سالسا بوتل میں ملنے والی ہر چیز سے بہتر ہے! یہ مزیدار، تیار ہونے میں تیز ہے اور تمام تازہ اجزا استعمال کرتی ہے جو شاید آپ کے باورچی خانے میں پہلے سے موجود ہوں۔ اگر آپ اسے چپس کے ساتھ پیش نہیں کرنا چاہتے تو کھیرے، اجوائن یا جکاما کے ساتھ آزمائیں۔ یہ ٹیکوز کے اوپر ڈالنے کے لیے بھی بہترین ٹاپنگ ہو گی!",
"8","10 چپس + ¼ کپ سالسا",
["تقریباً 80 ٹورٹیلا چپس (ملٹی گرین، اسکوپس)","1 کپ ڈبہ بند کالی پھلیاں (دھوئی ہوئی اور پانی نکالی ہوئی)","2 بڑے ٹماٹر (چوکور کٹے ہوئے)","1/4 کپ پیاز (باریک چوکور کٹی ہوئی)","1 لہسن کی جوئی (باریک کٹی ہوئی)","2 کھانے کے چمچ تازہ لائم کا رس","1/4 کپ تازہ ہرا دھنیا (کٹا ہوا)"],
["ایک درمیانے پیالے میں چپس کے سوا تمام اجزا ملا لیں۔","سالسا کو پیالے میں اور چپس کو ساتھ الگ رکھ کر پیش کریں۔"])
add(6435172,"بیف سانکوچو",
"میرے دادا دادی اپنے پچھواڑے میں کھلی آگ پر سانکوچو بناتے تھے؛ لکڑی کے دھوئیں نے اس ڈش میں بہت سا ذائقہ شامل کیا۔ سانکوچو ہسپانوی فعل sancochar سے آیا ہے، جس کا مطلب ہے ہلکا سا ابالنا۔ یہ ایک بہت بھرپور شوربہ ہے جو تمام لاطینی امریکہ میں عام ہے، جو سٹو کرنے والی مرغی، بیف اور اوجڑی سے بنتا ہے اور دوپہر کے کھانے میں پیش کیا جاتا ہے۔ فکر نہ کریں؛ اس ورژن کے لیے آپ کو آگ نہیں جلانی پڑے گی! ہسپانوی میں ترکیب: Receta en Español: Sancocho Carne de Res اپنا بغیر نمک کا ایڈوبو مسالا بنانے کے لیے، لیمن پیپر، لہسن پاؤڈر، پیاز پاؤڈر، خشک اوریگانو، خشک اجمود اور اچیوٹے پاؤڈر ہر ایک 1 کھانے کا چمچ اور زیرہ 1/2 کھانے کا چمچ ملا لیں۔ ہوا بند ڈبے میں 2 ہفتوں تک رکھیں۔",
"6","1 1/3 کپ",
["2 چائے کے چمچ زیتون کا تیل","1/2 پاؤنڈ کم چکنائی والا ٹاپ راؤنڈ بیف (1 انچ کے ٹکڑوں میں کٹا ہوا)","1 درمیانی پیاز (کٹی ہوئی)","1 درمیانی ہری شملہ مرچ (کٹی ہوئی)","1 ثابت کیوبانیل یا اناہائم مرچ (کٹی ہوئی)","2 ڈنٹھل اجوائن (کٹی ہوئی)","3 لہسن کی جوئیں (کٹی ہوئی)","32 اونس بغیر نمک کا بیف شوربہ","1/4 کپ بغیر اضافی نمک کی ٹماٹر ساس","1 کھانے کا چمچ ایڈوبو مسالا","1/2 چائے کا چمچ نمک","3 پتے تیز پات","3/4 پاؤنڈ (تقریباً 2 کپ) تازہ یا منجمد یوکا (پگھلایا ہوا اور 2 انچ کے ٹکڑوں میں کٹا ہوا)","1 درمیانا کچا ہرا پلانٹین (چھلا ہوا اور 1 انچ کے ٹکڑوں میں کٹا ہوا)","1 درمیانی چایوٹے اسکوائش (چھلی ہوئی اور 2 انچ کے چوکور ٹکڑوں میں کٹی ہوئی)","1 بڑا ٹماٹر (کٹا ہوا)","1 کپ تازہ کٹا ہوا ہرا دھنیا"],
["نان اسٹک ڈچ اوون یا بڑے نان اسٹک ساس پاٹ میں تیل درمیانی تیز آنچ پر گرم کریں۔ گوشت ڈالیں اور وقفے وقفے سے پلٹتے ہوئے بھورا ہونے تک پکائیں، تقریباً 5 منٹ۔ پیاز، شملہ مرچ، کیوبانیل، اجوائن اور لہسن ڈالیں۔ وقفے وقفے سے ہلاتے ہوئے سبزیاں نرم ہونے تک پکائیں، تقریباً 8 منٹ۔","شوربہ، ٹماٹر ساس، ایڈوبو مسالا، نمک اور تیز پات ڈالیں؛ ابال آنے دیں۔ آنچ درمیانی دھیمی کر دیں۔ ڈھانپ کر ہلکی آنچ پر پکائیں جب تک گوشت بس نرم نہ ہو جائے، تقریباً 1 گھنٹہ۔","یوکا، پلانٹین، چایوٹے اسکوائش اور ٹماٹر ڈالیں اور وقفے وقفے سے ہلاتے ہوئے پکائیں، جب تک گوشت اور سبزیاں کانٹے سے آسانی سے نہ چھد جائیں، تقریباً 40 منٹ۔","چولھے سے اتار لیں۔ تیز پات نکال کر پھینک دیں؛ ہرا دھنیا ملا دیں۔"])
add(6435330,"شیٹ پین مسو سالمن اور تل والا بوک چوئے",
"ایشیائی طرز کا یہ شیٹ پین ڈنر بھنے ہوئے بیبی بوک چوئے، چینی بند گوبھی کی ایک چھوٹی قسم، اور مسو میں میرینیٹ کی ہوئی ذائقہ دار سالمن پر مشتمل ہے۔ اگر آپ کو بوک چوئے نہ ملے تو اس کی جگہ برسلز اسپراؤٹس یا بروکلی اچھے رہیں گے۔ بہت کم کاربوہائیڈریٹ والے کھانے کے لیے اپنی پلیٹ میں براؤن چاول یا پھول گوبھی کے چاول کی سائیڈ شامل کریں۔",
"4","ایک سالمن فلیٹ اور بوک چوئے کا 1 سر (2 آدھے)",
["2 کھانے کے چمچ مسو پیسٹ","1/3 کپ چاول کا سرکہ","1 کھانے کا چمچ تل کا تیل (تقسیم کر کے)","2 لہسن کی جوئیں (باریک کٹی ہوئی)","1 کھانے کا چمچ کم سوڈیم تامری","4 (6 اونس کے) سالمن فلیٹ","4 سر بیبی بوک چوئے","2 چائے کے چمچ تل"],
["ایک درمیانے پیالے یا بڑے دوبارہ بند ہونے والے پلاسٹک بیگ میں مسو پیسٹ، چاول کا سرکہ، ½ کھانے کا چمچ تل کا تیل اور لہسن ملا لیں۔ سالمن ڈالیں اور میرینیڈ آہستگی سے لگا دیں۔ پیالے کو ڈھانپ دیں یا بیگ بند کر دیں اور 15 منٹ فریج میں میرینیٹ کریں (اگر وقت کم ہو تو میرینیٹ کرنے کا مرحلہ چھوڑ سکتے ہیں)۔","اوون کو 450°F پر پہلے سے گرم کریں۔ کنارے والی بیکنگ شیٹ پر پارچمنٹ پیپر بچھا دیں۔","بوک چوئے کی جڑوں والے سرے کاٹ دیں اور ہر ایک کو چوڑائی میں آدھا کاٹ لیں۔","سالمن فلیٹ کو میرینیڈ سے نکالیں اور کھال والی طرف نیچے رکھ کر تیار کی ہوئی بیکنگ شیٹ کے ایک سرے پر رکھیں۔ (باقی بچا ہوا میرینیڈ پھینک دیں۔)","بیکنگ شیٹ کے دوسرے سرے پر بوک چوئے کو کٹی ہوئی طرف نیچے رکھ کر سجائیں۔ باقی ½ کھانے کا چمچ تل کا تیل اور تامری چھڑکیں۔","8 منٹ تک بھونیں یا جب تک سالمن اچھی طرح پک نہ جائے اور بوک چوئے نرم نہ ہو جائیں۔","سالمن فلیٹ اور بوک چوئے کو پلیٹ میں رکھیں اور بوک چوئے پر تل چھڑکیں۔"])
add(6435485,"دھواں دار بیف برگر مشروم بن پر",
"یہ برگر کلاسک کے کم کاربوہائیڈریٹ متبادل کے طور پر دھواں دار بیف، پگھلی ہوئی چیڈر اور گرل کی ہوئی سبزیوں کو لذیذ پورٹوبیلو مشروم \"بن\" پر تہہ در تہہ رکھتا ہے۔ کدوکش کی ہوئی زوکینی ٹکیوں کو رسیلا رکھتی ہے اور چپکے سے سبزیوں کی ایک خوراک بھی شامل کرتی ہے۔",
"4","1 برگر",
["12 اونس کم چکنائی والا قیمہ بیف (3% چکنائی)","1 چائے کا چمچ اسموکڈ پیپریکا","1 چھوٹی زوکینی (کدوکش کی ہوئی، اضافی نمی نچوڑی ہوئی)","2 کھانے کے چمچ باربی کیو ساس (بغیر چینی)","4 ثابت پورٹوبیلو مشروم (بڑے)","1 کھانے کا چمچ ایکسٹرا ورجن زیتون کا تیل","4 قتلے چیڈر چیز (بغیر چکنائی والی)","1 درمیانی سرخ پیاز (1/4 انچ موٹے چھلوں میں کٹی ہوئی)","1 کپ بیبی ارگولا","1 درمیانا بیف اسٹیک ٹماٹر (کٹا ہوا)"],
["ایک بڑے پیالے میں قیمہ بیف، اسموکڈ پیپریکا، کدوکش کی ہوئی زوکینی اور باربی کیو ساس کا 1 کھانے کا چمچ ملا لیں۔ صاف ہاتھوں سے اچھی طرح ملائیں، پھر آمیزے سے چار ٹکیاں بنا لیں، ہر ایک تقریباً ¾ انچ موٹی۔","ایک بڑے گرل پین کو درمیانی تیز آنچ پر پہلے سے گرم کریں۔ ٹکیوں اور پورٹوبیلو مشروم پر زیتون کے تیل کا ہلکا برش پھیریں۔ مشروم کو گرل پر رکھیں اور ہر طرف 4-5 منٹ پکائیں جب تک نرم نہ ہو جائیں اور ہلکے جلنے کے نشان نہ پڑ جائیں۔","بیف کی ٹکیوں کو پہلی طرف تقریباً 4 منٹ پکائیں جب تک ہلکی جل نہ جائیں۔ ٹکیاں پلٹیں، مزید 2 منٹ پکائیں، پھر ہر ایک پر چیڈر چیز کا ایک قتلہ رکھیں۔ مزید 2 منٹ پکاتے رہیں جب تک چیز پگھل نہ جائے اور ٹکیاں اچھی طرح پک نہ جائیں۔","سرخ پیاز کے چھلوں کو ہر طرف تقریباً 2 منٹ گرل کریں جب تک ہلکے جل نہ جائیں۔","پیش کرنے کے لیے ہر گرل کیا ہوا مشروم کا ڈھکن پلیٹ پر گل (نیچے کی پتلی تہوں) والی طرف اوپر کر کے رکھیں۔ اوپر ارگولا، ٹماٹر کا ایک قتلہ، پگھلی ہوئی چیز والی بیف ٹکی، اور کچھ گرل کیے ہوئے پیاز کے چھلے رکھیں۔ باقی باربی کیو ساس چھڑکیں۔"])
add(6436140,"جھینگا کریول اور پھول گوبھی گرٹس",
"کلاسک گرٹس کے اس نئے انداز میں مکئی کی جگہ پھول گوبھی اور سفید پھلیاں استعمال ہوتی ہیں جو ایک کریمی متبادل بناتی ہیں اور جھینگوں کے مسالے کے ساتھ بہترین ملتا ہے۔ آپ چکن اسٹاک کی جگہ جھینگوں کے چھلکوں سے بنا فوری گھریلو اسٹاک استعمال کر سکتے ہیں۔ تیاری کا وقت کم کرنے کے لیے کیجن مسالا (عام طور پر مرچ، اسموکڈ پیپریکا، لال مرچ، لہسن، پیاز، نمک، کالی مرچ اور جڑی بوٹیوں کا مرکب) خریدنے پر غور کریں—اور یہ سبزیوں کے لیے بھی بہترین مسالا ہے۔ اگر خرید رہے ہوں تو بغیر نمک کا کیجن مسالا تجویز کیا جاتا ہے۔",
"4","1 1/2 کپ گرٹس اور 1 کپ کریول",
["2 چائے کے چمچ سبزی کا تیل","تقریباً 2 پاؤنڈ پھول گوبھی (تراشی ہوئی اور کدوکش کی ہوئی)","4 لہسن کی جوئیں (باریک کٹی ہوئی، تقسیم کر کے استعمال کریں)","1/2 ڈبہ کم سوڈیم سفید پھلیاں (پانی نکالی ہوئی اور دھوئی ہوئی)","1 1/2 کپ کم سوڈیم چکن شوربہ (تقسیم کر کے استعمال کریں)","1/2 کپ پانی","1 کھانے کا چمچ باریک کدوکش کی ہوئی پارمیزان چیز (اختیاری)","1/2 چائے کا چمچ پیاز پاؤڈر","1/4 چائے کا چمچ کالی مرچ","1 پاؤنڈ بڑے جھینگے (چھلے ہوئے اور آنت نکالے ہوئے)","1 1/2 چائے کے چمچ زیتون کا تیل","2 ڈنٹھل اجوائن (چوکور کٹی ہوئی)","1 چھوٹی پیلی پیاز (چوکور کٹی ہوئی)","1 ثابت ہری شملہ مرچ (چوکور کٹی ہوئی)","2 چائے کے چمچ بغیر نمک کا کریول مسالا","1 (14 اونس) ڈبہ ڈبہ بند چوکور کٹے ہوئے ٹماٹر","1 پتا تیز پات","1 ڈنٹھل ہری پیاز (اسکیلین) (کٹی ہوئی، سجاوٹ کے لیے)","1 چائے کا چمچ تیز ساس"],
["گرٹس کے لیے: ایک درمیانے برتن میں سبزی کا تیل درمیانی تیز آنچ پر گرم کریں۔ پھول گوبھی ڈالیں اور نرم اور ہلکی بھوری ہونے تک پکائیں، تقریباً 10 منٹ۔ 1 جوئی باریک کٹا لہسن ڈالیں اور خوشبو آنے تک گرم کریں، تقریباً 1 منٹ۔","پھلیاں، شوربہ اور پانی ڈالیں۔ 5 منٹ پکائیں۔ آنچ بند کر دیں۔ پارمیزان اور پیاز پاؤڈر ڈالیں۔ ماشر یا بلینڈر سے اس وقت تک مکس کریں جب تک بس کریمی نہ ہو جائے اور تھوڑی ساخت باقی رہے۔ ضرورت کے مطابق مزید پانی ڈالیں۔ کالی مرچ ڈالیں۔ پیش کرنے تک گرم رکھنے کے لیے ڈھانپ دیں۔","جھینگوں کے لیے: جھینگوں کو کاغذی تولیے سے خشک تھپتھپائیں۔ ایک بڑی کڑاہی میں 1½ چائے کے چمچ تیل درمیانی تیز آنچ پر گرم کریں اور جھینگے ایک تہہ میں ڈالیں۔ ایک طرف ہلکا سیئر کریں جب تک مڑ نہ جائیں اور ہلکے جل نہ جائیں۔ جھینگوں کو پلیٹ میں نکال لیں اور باقی تیل پین میں ڈالیں۔","اجوائن، پیاز اور شملہ مرچ پین میں ڈالیں۔ آنچ درمیانی کر دیں اور وقفے وقفے سے ہلاتے ہوئے نرم ہونے تک پکائیں لیکن زیادہ بھورا نہ ہو، تقریباً 7 منٹ۔ اگر سبزیاں پکتے وقت پین بہت خشک ہو جائے تو ضرورت کے مطابق پانی ڈالیں۔","باقی 3 جوئیں باریک کٹا لہسن اور مسالا ڈالیں اور خوشبو آنے تک گرم کریں، تقریباً 1 منٹ۔ ٹماٹر، شوربہ اور تیز پات ڈالیں۔ پین کی تہہ میں چپکے ہوئے ٹکڑوں کو چمچ سے کھرچ لیں۔ ابال آنے دیں اور پھر آنچ ہلکی کر دیں۔ 10 منٹ پکائیں جب تک گاڑھا نہ ہو جائے، تہہ جلنے سے بچانے کے لیے بار بار ہلاتے رہیں۔","پھول گوبھی کے \"گرٹس\" کے اوپر پیش کریں اور ہری پیاز اور تیز ساس سے سجائیں۔"])
add(6436642,"سرخ مسور کی دال کا حمص",
"سرخ مسور کی دال کا یہ حمص ایک کلاسک ڈپ کا سادہ، صحت بخش انداز ہے۔ چنوں کی جگہ یہ سرخ مسور کی دال استعمال کرتا ہے جو ہموار ساخت اور ہلکا، گری دار ذائقہ دیتی ہے۔ یہ چند بنیادی اجزا سے جلدی تیار ہو جاتا ہے اور غیر نشاستہ دار سبزیوں کے ساتھ یا سینڈوچز پر اسپریڈ کے طور پر لطف اٹھانا آسان ہے۔",
"8","2 کھانے کے چمچ",
["1 1/3 کپ پانی","1/3 کپ سرخ مسور کی دال (خشک)","1 کھانے کا چمچ زیتون کا تیل","1 کھانے کا چمچ تاہینی","1 کھانے کا چمچ لیموں کا رس","1/2 چائے کا چمچ لہسن (باریک کٹا ہوا)","1/2 چائے کا چمچ پسا ہوا زیرہ","1/4 چائے کا چمچ نمک","1/4 چائے کا چمچ کالی مرچ"],
["ایک چھوٹے ساس پین میں پانی اور خشک سرخ مسور کی دال ملائیں اور درمیانی تیز آنچ پر ابال لیں۔","آنچ دھیمی کر دیں اور ڈھانپ کر ہلکی آنچ پر پکائیں، وقفے وقفے سے ہلاتے ہوئے، تقریباً 30 منٹ یا جب تک دال ٹوٹ کر نرم نہ ہو جائے۔ ٹھنڈا کریں اور فوڈ پروسیسر میں منتقل کریں۔","زیتون کا تیل، تاہینی، لیموں کا رس، باریک کٹا لہسن، زیرہ، نمک اور کالی مرچ ڈالیں اور 30-60 سیکنڈ تک ہموار ہونے تک پروسیس کریں، ضرورت کے مطابق رک کر اطراف سے آمیزہ کھرچ لیں۔","ہوا بند ڈبے میں منتقل کریں اور پیش کرنے کے وقت تک 5 دن تک فریج میں رکھیں۔"])
add(6437099,"کیلیفورنیا کھجور اور ہریسہ سالمن",
"اس ذائقہ دار سالمن ڈش میں کیلیفورنیا کھجوروں کی قدرتی مٹھاس ہریسہ کی دھواں دار تیزی کو متوازن کرتی ہے اور ساتھ ہی ریشہ، اینٹی آکسیڈنٹس اور ضروری غذائی اجزا شامل کرتی ہے۔ ہریسہ شمالی افریقہ کا مرچ کا پیسٹ ہے جو بھنی ہوئی سرخ مرچوں اور مسالوں سے بنتا ہے۔ اگر یہ آپ کے گروسری اسٹور پر نہ ملے تو آپ ایڈوبو ساس میں چپوٹلے استعمال کر سکتے ہیں جو اسی طرح کی دھواں دار تیزی دیتی ہے۔ جڑی بوٹیاں اور مسالے اضافی چکنائی، سوڈیم یا چینی شامل کیے بغیر اپنے کھانوں کا ذائقہ بڑھانے کا بہترین طریقہ ہیں۔ یہ بہت کم کاربوہائیڈریٹ اور کم کاربوہائیڈریٹ والی ترکیب دل کے لیے بھی صحت بخش ہے۔",
"4","1 سالمن (4 اونس) فلیٹ",
["5 ثابت کیلیفورنیا کھجوریں (گٹھلی نکالی ہوئی)","3 کھانے کے چمچ پانی","2 کھانے کے چمچ زیتون کا تیل","1 کھانے کا چمچ ہریسہ یا تیز مرچ کا پیسٹ","1 کھانے کا چمچ تازہ لائم کا رس","3 لہسن کی جوئیں (باریک کٹی ہوئی)","1/2 چائے کا چمچ پسا ہوا زیرہ","1/2 چائے کا چمچ پسا ہوا دھنیا","1/4 چائے کا چمچ کوشر نمک","4 ثابت ساکی آئی سالمن (4 اونس فلیٹ)","2 کھانے کے چمچ تازہ ہرا دھنیا (کٹا ہوا)","1 ثابت لائم (4 پھانکوں میں کٹا ہوا)"],
["اوون کو 400°F پر پہلے سے گرم کریں۔","3 کھجوروں کو موٹا موٹا کاٹ لیں اور پانی کے ساتھ ایک چھوٹے پیالے میں رکھیں۔ باقی 2 کھجوروں کو کاٹ کر بعد کے لیے الگ رکھ دیں۔","کھجوروں کا پیالہ مائیکرو ویو میں 45 سیکنڈ سے 1 منٹ تک نرم ہونے تک رکھیں۔ پیالہ احتیاط سے نکالیں اور کھجوروں کو کانٹے سے میش کر کے گاڑھا پیسٹ بنا لیں۔ زیتون کا تیل، ہریسہ پیسٹ، لائم کا رس، لہسن، زیرہ، دھنیا اور نمک ڈالیں اور ملنے تک ہلائیں۔","سالمن فلیٹ کو نان اسٹک اسپرے لگی ہوئی ایک بڑی بیکنگ ڈش میں رکھیں۔ کھجور اور ہریسہ کی چٹنی سالمن کے اوپر چمچ سے ڈالیں اور اسے مکمل ڈھانپ دیں۔ باقی کٹی ہوئی کھجوریں اوپر چھڑکیں۔","10–14 منٹ تک بیک کریں، یا جب تک سالمن اندر سے 145°F تک نہ پک جائے اور کانٹے سے آسانی سے ریشہ ریشہ نہ ہو جائے۔ اوون سے نکالیں اور سالمن کے اوپر کٹا ہوا ہرا دھنیا ڈالیں۔","سالمن کا ہر ٹکڑا ایک لائم کی پھانک کے ساتھ پیش کریں جسے اوپر نچوڑا جا سکے۔"])
add(6437901,"کلاسک اطالوی پانزانیلا سلاد",
"ڈبل روٹی اور ٹماٹر کا یہ کلاسک سلاد کسی بھی بھنے ہوئے گوشت یا مرغی کے مرکزی کھانے کے ساتھ اچھا لگتا ہے۔ ترکیب کو دوگنا کر لیں تو یہ اس سال آپ کی چھٹیوں کی دعوت میں بھی بہترین سائیڈ ڈش بن سکتا ہے!",
"4","ترکیب کا 1/4",
["2 درمیانے ٹماٹر (1 انچ کے چوکور ٹکڑوں میں کٹے ہوئے (یا 2 کپ چیری ٹماٹر، آدھے کٹے ہوئے))","1/2 چائے کا چمچ کوشر نمک","5 قتلے ملٹی گرین اطالوی ڈبل روٹی","1 کپ کھیرا (لمبائی میں چار حصوں میں کاٹ کر باریک قتلے کیا ہوا (تقریباً آدھا انگلش کھیرا))","2 ڈنٹھل اجوائن (1/2 انچ موٹی کٹی ہوئی)","1 چھوٹی سرخ پیاز (آدھی کاٹ کر باریک قتلے کی ہوئی)","1/4 چائے کا چمچ تازہ پسی ہوئی کالی مرچ","2 کھانے کے چمچ سرخ شراب کا سرکہ","2 کھانے کے چمچ ایکسٹرا ورجن زیتون کا تیل","1/2 کپ تازہ تلسی کے پتے (پٹیوں میں پھاڑے ہوئے)","1 کپ چپٹے اطالوی اجمود کے پتے (موٹے موٹے کٹے ہوئے)"],
["ٹماٹروں کو ایک بڑے سلاد کے پیالے میں رکھیں اور نمک چھڑکیں۔ 5 منٹ رکھا رہنے دیں۔","ڈبل روٹی توڑ کر ٹماٹروں میں ڈالیں۔ سلاد کے باقی اجزا ڈالیں اور اچھی طرح ملا لیں۔"])
add(6438385,"مسالے دار جھینگے گرل کیے ہوئے لیموں کے ساتھ",
"یہ تیز اور ذائقہ دار کم کاربوہائیڈریٹ ڈش ہے جو بنانے میں آسان ہے۔ جھینگوں کو گرم مسالوں سے ذائقہ دیا جاتا ہے اور اضافی تازگی کے لیے دھواں دار، گرل کیے ہوئے لیموں کا رس نچوڑ کر مکمل کیا جاتا ہے۔",
"5","3 اونس",
["2 کھانے کے چمچ تازہ اجمود","3 درمیانے لیموں (آدھے کٹے ہوئے)","1/4 چائے کا چمچ کالی مرچ","1/4 چائے کا چمچ نمک","1/4 چائے کا چمچ پسا ہوا دھنیا","2 چائے کے چمچ چلی پاؤڈر","2 چائے کے چمچ پسا ہوا زیرہ","1 1/2 کھانے کے چمچ زیتون کا تیل","1 پاؤنڈ جھینگے (چھلے ہوئے اور آنت نکالے ہوئے، دم کے ساتھ)","1 اسپرے، 0.25 گرام نان اسٹک کوکنگ اسپرے"],
["گرل کی جالی پر کوکنگ اسپرے لگا دیں۔ گرل کو درمیانی تیز آنچ پر پہلے سے گرم کریں۔ اگر آپ کو لگتا ہے کہ جھینگے گرل کی جالی سے نیچے گر جائیں گے تو جھینگے گرل کرنے کے لیے فش باسکٹ تیار کریں اور باسکٹ کے اندر کوکنگ اسپرے لگا دیں۔"])
add(6438939,"کیلے کی پاپسیکلز",
"یہ کیلے کی پاپسیکلز ٹھنڈک پانے کا ایک میٹھا طریقہ ہیں۔ ذیابیطس کے لیے موزوں اور بچوں کی پسندیدہ میٹھی ڈش جو گرمیوں میں بہترین ہے۔",
"4","1 پاپسیکل",
["2 درمیانے کیلے (پکے ہوئے)","1/2 کپ کم چکنائی والا یونانی دہی (سادہ)","2 کھانے کے چمچ بغیر چینی کا کثیر المقاصد شربت"],
["بلینڈر میں کیلے، یونانی دہی اور شربت ملا لیں۔","آمیزے کو پاپسیکل کے سانچوں میں ڈالیں اور 8 گھنٹے یا رات بھر فریز کریں۔"])
add(6438996,"دال اور سبزیوں کا اسٹر فرائی",
"دال اور سبزیوں کا یہ اسٹر فرائی ایک صحت بخش اور تسلی بخش سبزی خوروں کی ڈش ہے جو دال اور رنگ برنگی سبزیوں سے پروٹین، ریشے اور وٹامنز کا اچھا توازن فراہم کرتی ہے۔ یہ ایک ہمہ جہت ترکیب ہے جس میں آپ اپنی پسندیدہ سبزیاں شامل کر سکتے ہیں۔",
"4","1.5 کپ",
["1 کپ بھوری دال (خشک، دھوئی ہوئی اور پانی نکالی ہوئی)","2 1/2 کپ کم سوڈیم سبزیوں کا شوربہ","2 کھانے کے چمچ کم سوڈیم سویا ساس","1 کھانے کا چمچ تل کا تیل","2 کھانے کے چمچ چاول کا سرکہ","1 کھانے کا چمچ میپل شربت","1 چائے کا چمچ سبزی کا تیل","3 لہسن کی جوئیں (باریک کٹی ہوئی)","1 کھانے کا چمچ تازہ ادرک (کدوکش کی ہوئی)","3 کپ بروکلی (پھولیاں)","2 درمیانی گاجریں (پتلے گول قتلوں میں کٹی ہوئی)","1 درمیانی سرخ شملہ مرچ (باریک کٹی ہوئی)","1 درمیانی پیلی شملہ مرچ (باریک کٹی ہوئی)","1 کپ شوگر اسنیپ مٹر (تراشے ہوئے)","1 کھانے کا چمچ تل","2 ڈنٹھل ہری پیاز (کٹی ہوئی)"],
["ایک درمیانے ساس پین میں دال اور سبزیوں کا شوربہ ملا لیں۔ ابال آنے دیں، پھر آنچ کم کر دیں، ڈھانپ دیں، اور 15–20 منٹ ہلکی آنچ پر پکائیں، یا جب تک دال نرم ہو جائے لیکن اپنی شکل برقرار رکھے۔ اضافی مائع نکال دیں۔","ایک چھوٹے پیالے میں سویا ساس، تل کا تیل، چاول کا سرکہ اور میپل شربت پھینٹ کر ملا لیں۔ الگ رکھ دیں۔","ایک بڑی کڑاہی یا وک میں سبزی کا تیل درمیانی تیز آنچ پر گرم کریں۔ باریک کٹا لہسن اور کدوکش کی ہوئی ادرک ڈالیں، اور خوشبو آنے تک 30 سیکنڈ بھونیں۔","بروکلی، گاجر، سرخ شملہ مرچ، پیلی شملہ مرچ اور اسنیپ مٹر کڑاہی میں ڈالیں۔ 5–7 منٹ اسٹر فرائی کریں جب تک سبزیاں نرم لیکن کرکری نہ ہو جائیں۔","پکی ہوئی دال کو سبزیوں کے آمیزے میں شامل کریں۔","تیار کی ہوئی چٹنی دال اور سبزیوں پر ڈالیں۔ اچھی طرح ہلائیں تاکہ ہر چیز ذائقہ دار چٹنی میں لپٹ جائے۔","مزید 2–3 منٹ پکاتے رہیں جب تک سب کچھ اچھی طرح گرم نہ ہو جائے۔","چاہیں تو تل اور کٹی ہوئی ہری پیاز سے سجائیں۔"])
add(6440574,"ارگولا سلاد اخروٹ اور بکری کی چیز کے ساتھ",
"ارگولا کا تیکھا ذائقہ کریمی بکری کی چیز اور مٹی کی سی خوشبو والے اخروٹ کے ساتھ مل کر ایک تسلی بخش، ذیابیطس کے لیے موزوں سلاد بناتا ہے۔ جب آپ زیادہ محنت کیے بغیر تھوڑا خاص کچھ بنانا چاہیں تو اسے اپیٹائزر یا سائیڈ سلاد کے طور پر پیش کریں۔",
"6","1 کپ",
["6 کپ ارگولا","1/2 کپ اخروٹ (بھنے ہوئے اور کٹے ہوئے)","1/4 کپ بکری کی چیز (ریزہ ریزہ کی ہوئی)","1 کپ چیری ٹماٹر (آدھے کٹے ہوئے)","1/4 کپ ہلکی بالسامک ونیگریٹ"],
["ایک بڑے سلاد کے پیالے میں ارگولا، بھنے ہوئے اور کٹے ہوئے اخروٹ، ریزہ ریزہ بکری کی چیز، اور آدھے کٹے ہوئے چیری ٹماٹر ملا لیں۔","ایک چھوٹے پیالے میں بالسامک ونیگریٹ ڈریسنگ، ایکسٹرا ورجن زیتون کا تیل، نمک اور کالی مرچ پھینٹ کر ملا لیں۔","ڈریسنگ سلاد پر ڈالیں۔","سلاد کو آہستگی سے ملائیں تاکہ ڈریسنگ یکساں طور پر لگ جائے۔"])
add(6442793,"چکن، برسلز اسپراؤٹس اور مشروم بیک",
"چکن، برسلز اسپراؤٹس اور مشروم کا یہ بیک ایک تیز ایک کڑاہی والی ڈش ہے جو آپ کے گھر والوں کو پسند آئے گی۔ یہ ترکیب ریشے کا بہترین ذریعہ ہے، سبزیوں سے بھرپور ہے اور پروٹین کا اچھا ذریعہ ہے۔",
"4","2 کپ",
["1 کھانے کا چمچ زیتون کا تیل","1 چھوٹی پیلی پیاز (چوکور کٹی ہوئی)","1 1/2 پاؤنڈ تازہ برسلز اسپراؤٹس (تراشے ہوئے اور آدھے کٹے ہوئے)","1 پاؤنڈ چکن بریسٹ (چوکور ٹکڑے)","8 اونس کریمینی (بیبی بیلا) مشروم (کٹے ہوئے)","1 چائے کا چمچ اطالوی مسالا","1/2 چائے کا چمچ کوشر نمک","1/4 چائے کا چمچ کالی مرچ","1 کھانے کا چمچ 1% دودھ","1/4 کپ موزریلا چیز (جزوی سکِم، کدوکش کی ہوئی)","2 کھانے کے چمچ سادہ بغیر چکنائی والا یونانی دہی"],
["اوون کو 375 ڈگری فارن ہائیٹ پر پہلے سے گرم کریں۔","ایک بڑی کڑاہی میں زیتون کا تیل درمیانی آنچ پر گرم کریں۔ پیاز، برسلز اسپراؤٹس، چکن، مشروم، اطالوی مسالا، نمک اور کالی مرچ ڈالیں۔ درمیانی آنچ پر وقفے وقفے سے ہلاتے ہوئے تقریباً 10 منٹ پکائیں، جب تک سبزیاں نرم نہ ہو جائیں اور چکن اچھی طرح پک نہ جائے۔","جب چکن اور سبزیاں پک رہی ہوں تو ایک چھوٹے پیالے میں دودھ اور دہی ملنے تک پھینٹ لیں۔","دودھ اور دہی کو چکن اور سبزیوں کے آمیزے پر ڈالیں اور لپیٹنے کے لیے ہلائیں۔","اوپر چیز چھڑکیں اور کڑاہی کو اوون میں رکھیں اور 15 منٹ پکائیں، جب تک چیز پگھل کر بلبلے نہ بنانے لگے۔"])
add(6443719,"سالمن اور ایسپیرگس گریمولاتا",
"پارچمنٹ پیپر کے پیکٹ مچھلی کو سبزیوں اور مسالوں کے ساتھ بھاپ میں پکانے کا ایک سادہ اور نفیس طریقہ ہیں۔ اگر آپ کے پاس پارچمنٹ پیپر نہیں ہے تو آپ اس کی جگہ ایلومینیم ورق استعمال کر سکتے ہیں۔ زیادہ گریمولاتا بنا لیں اور کسی اور رات بھاپ میں پکی سبزیوں یا بیک کیے ہوئے چکن میں ذائقہ بڑھانے کے لیے استعمال کریں۔",
"2","4 اونس سالمن + 1/2 کپ ایسپیرگس + 2 کھانے کے چمچ گریمولاتا",
["1 اسپرے، 0.25 گرام نان اسٹک کوکنگ اسپرے","8 اونس ساکی آئی سالمن (کھال کے ساتھ، 2 حصوں میں کٹی ہوئی)","1 درمیانا شیلوٹ (باریک کٹا ہوا)","1/8 چائے کا چمچ کالی مرچ","8 ڈنڈیاں ایسپیرگس (تراشی ہوئی اور 1 انچ کے ٹکڑوں میں کٹی ہوئی)","1/4 کپ تازہ اجمود","1/2 لہسن کی جوئی","3/4 چائے کا چمچ لیموں کا چھلکا"],
["اوون کو 425°F پر پہلے سے گرم کریں۔","کوکنگ پارچمنٹ کی 15 x 10 انچ کی شیٹ کاٹ لیں اور 7.5 x 10 انچ کا مستطیل بنانے کے لیے آدھا موڑ دیں۔ موڑ کے نچلے حصے سے شروع کرتے ہوئے آدھے دل کی شکل میں کاٹیں۔ کھولیں اور کوکنگ اسپرے لگائیں۔ دوسری شیٹ کے ساتھ یہی دہرائیں۔ سالمن کا ایک فلیٹ کھال والی طرف نیچے رکھ کر ہر پارچمنٹ دل کے آدھے حصے کے بیچ میں رکھیں۔ ہر فلیٹ پر آدھے شیلوٹ، مرچ اور ایسپیرگس ڈالیں۔","دل کے دوسرے آدھے حصوں کو مچھلی اور ایسپیرگس پر موڑ دیں۔ ہر پیکٹ کو دل کے اوپر ایک چھوٹی تہہ بنا کر اور کنارے کو نیچے تک موڑتے ہوئے بند کریں۔ نوک کو مضبوطی سے بند کرنے کے لیے مروڑ دیں۔ بند پیکٹوں کو بیکنگ شیٹ پر رکھیں، اور 10 منٹ بیک کریں۔","اسی دوران، گریمولاتا بنائیں: اجمود اور لہسن کو ایک ساتھ باریک کاٹ لیں۔ لیموں کا چھلکا ڈالیں، اور اچھی طرح ملنے تک کاٹتے رہیں۔","پارچمنٹ پیکٹ اوون سے نکالیں۔ 3 منٹ رکھا رہنے دیں۔ بھاپ سے جلنے سے بچنے کی احتیاط کرتے ہوئے، ہر پیکٹ کے بیچ میں X کاٹیں۔ جانچ لیں کہ سالمن کانٹے سے آسانی سے ریشہ ریشہ ہوتی ہے۔ اگر ضروری ہو تو پکانا مکمل کرنے کے لیے پیکٹوں کو 1 سے 2 منٹ کے لیے اوون میں واپس رکھیں۔","پیکٹوں کو پلیٹ میں منتقل کریں اور باقی حصہ بھی کھول دیں۔ ہر ایک پر 2 چائے کے چمچ گریمولاتا چھڑکیں۔"])
add(6444169,"سردیوں کا کرودیتے جڑی بوٹیوں والے ایولی کے ساتھ",
"جڑی بوٹیوں والے ایولی کے ساتھ سردیوں کا کرودیتے ایک تازہ اور جاندار اپیٹائزر ہے جس میں موسمی سبزیوں کا انتخاب ذائقہ دار جڑی بوٹیوں سے بھرے ایولی کے ساتھ پیش کیا جاتا ہے۔ یہ ترکیب سردیوں کی محفلوں اور تعطیلات کی دعوتوں میں بہترین اضافہ ہے۔",
"4","2 کھانے کے چمچ ایولی + 1 کپ سبزیاں",
["4 کپ مختلف سبزیاں (جیسے گاجر، مولی، اجوائن، بروکلی، پھول گوبھی، چیری ٹماٹر، اور شملہ مرچ کی پٹیاں)","2 چائے کے چمچ زیتون کا تیل (چھڑکنے کے لیے)","1/2 کپ مایونیز (کم چکنائی والی)","1 کھانے کا چمچ لیموں کا رس","1 کھانے کا چمچ میپل شربت","2 لہسن کی جوئیں (کدوکش کی ہوئی)","1/4 چائے کا چمچ نمک","1/4 چائے کا چمچ کالی مرچ","2 کھانے کے چمچ تازہ جڑی بوٹیاں (جیسے روزمیری، چائیوز اور اجمود؛ باریک کٹی ہوئی)"],
["سب سے پہلے گاجر، مولی، اجوائن، بروکلی، پھول گوبھی، چیری ٹماٹر اور شملہ مرچ کی پٹیوں جیسی سردیوں کی غیر نشاستہ دار سبزیاں دھو کر تیار کریں۔ انہیں ڈبونے میں آسانی کے لیے ایک نوالے کے سائز کی تیلیوں یا پھولیوں میں کاٹ لیں۔","جب سبزیاں تیار ہو جائیں تو انہیں پیش کرنے والی تھالی میں خوبصورتی سے سجائیں اور ایک پرکشش نمائش بنائیں۔ ان کا ذائقہ بڑھانے کے لیے سبزیوں پر ہلکا سا زیتون کا تیل چھڑکیں اور چٹکی بھر نمک اور کالی مرچ ڈالیں۔","ایک چھوٹا پیالہ لیں اور 1/2 کپ مایونیز کو تازہ لیموں کا رس، میپل شربت، کدوکش کیا ہوا لہسن، نمک اور کالی مرچ اور باریک کٹی ہوئی تازہ جڑی بوٹیوں، جیسے روزمیری، چائیوز اور اجمود کے ساتھ ملا لیں۔ آمیزے کو اس وقت تک ہلائیں جب تک جڑی بوٹیاں ایولی میں یکساں طور پر تقسیم نہ ہو جائیں۔ جڑی بوٹیوں والے ایولی میں نمک اور کالی مرچ ڈالیں، اور جڑی بوٹیاں اپنی پسند کے مطابق ایڈجسٹ کریں۔"])
save(4)
